TASK_NAME = "mawesi-sync-code-repos"


def schedule(apps, schema_editor):
    """Corre plane_mawesi.tasks.sync_code_repos cada 5 minutos (code.SYNC_MINUTES)."""
    IntervalSchedule = apps.get_model("django_celery_beat", "IntervalSchedule")
    PeriodicTask = apps.get_model("django_celery_beat", "PeriodicTask")
    every, _ = IntervalSchedule.objects.get_or_create(every=5, period="minutes")
    PeriodicTask.objects.update_or_create(
        name=TASK_NAME, defaults={"task": "plane_mawesi.tasks.sync_code_repos", "interval": every, "enabled": True}
    )


def unschedule(apps, schema_editor):
    apps.get_model("django_celery_beat", "PeriodicTask").objects.filter(name=TASK_NAME).delete()


